import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { isCaffePrototxt, parseCaffe, parseCaffemodel, parseCaffePrototxt } from "../src/formats/caffe";
import { parseProtoText } from "../src/common/protoText";

// Fixtures (see fixtures/README.md): BVLC LeNet deploy + train_val prototxts,
// SqueezeNet v1.1 deploy prototxt, and TinyNet .prototxt/.caffemodel files
// generated by fixtures/scripts/make_caffe.py from real torch weights.
const dir = join(__dirname, "fixtures", "caffe");
const bytes = (f: string) => new Uint8Array(readFileSync(join(dir, f)));
const text = (f: string) => readFileSync(join(dir, f), "utf8");
const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);

describe("protobuf text format", () => {
  it("parses nested messages, repeated fields, enums, lists and comments", () => {
    const m = parseProtoText(`# c\nname: "n" a { b: 1 b: 2 e: MAX } c: [1, 2.5] d: true s: 'x' "y"`);
    expect(m.name).toEqual(["n"]);
    expect((m.a[0] as Record<string, unknown[]>).b).toEqual([1, 2]);
    expect((m.a[0] as Record<string, unknown[]>).e).toEqual(["MAX"]);
    expect(m.c).toEqual([1, 2.5]);
    expect(m.d).toEqual([true]);
    expect(m.s).toEqual(["xy"]);
  });
});

describe("caffe prototxt", () => {
  it("LeNet deploy: graph, shapes, params, flops", () => {
    const src = text("lenet.prototxt");
    expect(isCaffePrototxt(src)).toBe(true);
    const m = parseCaffePrototxt(src, "lenet.prototxt");
    expect(m.format).toBe("Caffe prototxt");
    expect(m.doc).toBe("LeNet");
    expect(m.layers.map((l) => l.type)).toEqual([
      "Input", "Convolution", "Pooling", "Convolution", "Pooling", "InnerProduct", "ReLU", "InnerProduct", "Softmax",
    ]);
    expect(m.edges).toHaveLength(8);
    expect(m.inputShape).toEqual([64, 1, 28, 28]);
    expect(m.outputShape).toEqual([64, 10]);
    const by = (n: string) => m.layers.find((l) => l.name === n)!;
    expect(by("conv1").shape).toBe("64×20×24×24");
    expect(by("pool2").shape).toBe("64×50×4×4");
    expect(by("ip1").shape).toBe("64×500");
    expect(by("conv1").params).toBe(520);
    expect(by("conv2").params).toBe(25050);
    expect(by("ip1").params).toBe(400500);
    expect(sum(m.layers.map((l) => l.params))).toBe(431080);
    expect(by("conv1").macs).toBe(64 * 20 * 24 * 24 * 25);
    expect(by("ip1").group).toBe("head");
    expect(by("prob").group).toBe("output");
    expect(by("data").group).toBe("input");
    // In-place ReLU (top == bottom) chains ip1 → relu1 → ip2.
    expect(m.edges).toContainEqual([by("ip1").id, by("relu1").id]);
    expect(m.edges).toContainEqual([by("relu1").id, by("ip2").id]);
  });

  it("train_val: drops TRAIN-only layers, keeps TEST data + loss layers", () => {
    const m = parseCaffe(bytes("lenet_train_test.prototxt"), "lenet_train_test.prototxt");
    expect(m.layers).toHaveLength(10);
    expect(m.layers[0].type).toBe("Data");
    expect(m.layers[0].attr.phase).toBe("TEST");
    const loss = m.layers.find((l) => l.type === "SoftmaxWithLoss")!;
    expect(loss.group).toBe("output");
    expect(m.layers.find((l) => l.type === "Accuracy")!.ins.map((i) => i.n)).toEqual(["ip2", "label"]);
  });

  it("SqueezeNet v1.1: fire modules, concat, ceil pooling, 1.23M params", () => {
    const m = parseCaffePrototxt(text("squeezenet_v1.1.prototxt"), "squeezenet.prototxt");
    const by = (n: string) => m.layers.find((l) => l.name === n)!;
    expect(by("conv1").shape).toBe("10×64×113×113");
    expect(by("pool1").shape).toBe("10×64×56×56"); // ceil rounding
    expect(by("fire2/concat").shape).toBe("10×128×56×56");
    expect(by("fire2/concat").ins).toHaveLength(2);
    expect(by("pool10").shape).toBe("10×1000×1×1");
    expect(m.layers.filter((l) => l.type === "Concat")).toHaveLength(8);
    expect(sum(m.layers.map((l) => l.params))).toBe(1235496);
    expect(m.outputShape).toEqual([10, 1000, 1, 1]);
  });

  it("legacy V1 `layers {}` with enum types and net-level inputs", () => {
    const src = `name: "old" input: "data" input_dim: 1 input_dim: 3 input_dim: 8 input_dim: 8
layers { name: "conv" type: CONVOLUTION bottom: "data" top: "conv" convolution_param { num_output: 4 kernel_size: 3 } }
layers { name: "relu" type: RELU bottom: "conv" top: "conv" }
layers { name: "fc" type: INNER_PRODUCT bottom: "conv" top: "fc" inner_product_param { num_output: 2 } }`;
    const m = parseCaffePrototxt(src, "old.prototxt");
    expect(m.layers.map((l) => l.type)).toEqual(["Input", "Convolution", "ReLU", "InnerProduct"]);
    expect(m.layers[1].shape).toBe("1×4×6×6");
    expect(m.layers[3].params).toBe(4 * 36 * 2 + 2);
    expect(m.edges).toEqual([[0, 1], [1, 2], [2, 3]]);
  });
});

describe("caffemodel (binary)", () => {
  it("TinyNet: blobs give params + weight stats; matches the prototxt", () => {
    const m = parseCaffe(bytes("tinynet.caffemodel"), "tinynet.caffemodel");
    expect(m.format).toBe("Caffe");
    expect(m.layers).toHaveLength(14);
    expect(m.edges).toHaveLength(14);
    expect(sum(m.layers.map((l) => l.params))).toBe(1155);
    const by = (n: string) => m.layers.find((l) => l.name === n)!;
    expect(by("conv1").params).toBe(224);
    expect(by("conv1").w?.shape).toEqual([8, 3, 3, 3]);
    expect(by("conv1").w?.std).toBeGreaterThan(0);
    expect(by("bn1").params).toBe(17);
    expect(by("conv3").shape).toBe("1×16×8×8");
    expect(by("gap").shape).toBe("1×16×1×1");
    expect(by("fc").shape).toBe("1×10");
    expect(by("add").ins.map((i) => i.n)).toEqual(["conv2", "pool1"]);
    expect(m.edges).toContainEqual([by("pool1").id, by("add").id]);
    expect(by("prob").group).toBe("output");

    const t = parseCaffePrototxt(text("tinynet.prototxt"), "tinynet.prototxt");
    expect(t.layers.map((l) => l.params)).toEqual(m.layers.map((l) => l.params));
    expect(t.layers.map((l) => l.shape)).toEqual(m.layers.map((l) => l.shape));
    expect(t.edges).toEqual(m.edges);
  });

  it("legacy V1 binary NetParameter (layers=2, enum types, input_dim)", () => {
    const m = parseCaffemodel(bytes("tinynet_v1.caffemodel"), "tinynet_v1.caffemodel");
    expect(m.layers.map((l) => l.type)).toEqual(["Input", "Convolution", "ReLU", "Pooling", "InnerProduct", "Softmax"]);
    expect(m.inputShape).toEqual([1, 3, 32, 32]);
    const fc = m.layers.find((l) => l.name === "fc")!;
    expect(fc.w?.shape).toEqual([10, 2048]);
    expect(fc.params).toBe(20490);
    expect(fc.shape).toBe("1×10");
    expect(m.layers.find((l) => l.name === "pool1")!.shape).toBe("1×8×16×16");
  });
});
